# D2B Powder Diffractometer Instrument
# Parameters: lambda=1, DM=0, Powder=Na2Ca3Al2F14.laz, RV=-1, L1=16.05, L2=2.645, L3=1.3, verbose=1, ALPHA1=18, ALPHA2=11, ALPHA3=5, ETA=12, THETA_M=67.5, TILT=0, SM=1, Dheight=0.3, coating=0

#include "mcstas3.h"

# Define constants
double K2V = 1.23984193e-6; # [m*meV]
double VS2E = 1.23984193e-6; # [m*meV]
double RAD2DEG = 180.0 / 3.141592653589793;
double DEG2RAD = 3.141592653589793 / 180.0;

# Compute derived quantities
double L;
double KI, Vi, EI;
double ALPHA3_Opt;
double RV;
double L0;

# Check if THETA_M is provided and compute missing parameters
if (!THETA_M && lambda && DM) {
    THETA_M = asin(lambda/(2*DM)) * RAD2DEG;
} else if (THETA_M && !lambda && DM) {
    lambda = fabs(sin(THETA_M * DEG2RAD)) * 2 * DM;
} else if (THETA_M && lambda) {
    DM = fabs(lambda / sin(THETA_M * DEG2RAD) / 2.0);
}
if (!THETA_M || !DM || !lambda) {
    exit(fprintf(stderr, "ILL_D2B: ERROR: Monochromator take-off, d-spacing or wavelength is null (THETA_M=%g, DM=%g, lambda=%g). Abort.\n", THETA_M, DM, lambda));
}

# Compute L
if (!L1) {
    L = L2;
} else {
    L = 1 / (1 / L1 + 1 / L2);
}

# Compute RV
if (RV < 0) {
    RV = 2 * L * sin(THETA_M * DEG2RAD);
}

# Compute KI, Vi, EI
KI = 2 * PI / lambda;
Vi = K2V * fabs(KI);
EI = VS2E * Vi * Vi;

# Compute resolution parameters
if (ALPHA1 <= 0) {
    ALPHA1 = 600;
}
if (ALPHA2 <= 0) {
    ALPHA2 = 600;
}
if (ALPHA3 <= 0) {
    ALPHA3 = 600;
}
if (ETA <= 0) {
    ETA = 30;
}

U = 4 * (ALPHA1 * ALPHA1 * ALPHA2 * ALPHA2 + ALPHA1 * ALPHA1 * ETA * ETA + ALPHA2 * ALPHA2 * ETA * ETA) 
   / (tan(THETA_M * DEG2RAD) * tan(THETA_M * DEG2RAD) * (ALPHA1 * ALPHA1 + ALPHA2 * ALPHA2 + 4 * ETA * ETA));
V = 4 * ALPHA2 * ALPHA2 * (ALPHA1 * ALPHA1 + 2 * ETA * ETA) 
   / (tan(THETA_M * DEG2RAD) * (ALPHA1 * ALPHA1 + ALPHA2 * ALPHA2 + 4 * ETA * ETA));
W = ALPHA3 * ALPHA3 + (ALPHA1 * ALPHA1 * ALPHA2 * ALPHA2 + 4 * ALPHA2 * ALPHA2 * ETA * ETA) 
   / (ALPHA1 * ALPHA1 + ALPHA2 * ALPHA2 + 4 * ETA * ETA);
L0 = (ALPHA1 * ETA * ALPHA2 * ALPHA3 / tan(fabs(THETA_M) * DEG2RAD)) 
   / sqrt(ALPHA1 * ALPHA1 + ALPHA2 * ALPHA2 + 4 * ETA * ETA);
ALPHA3_Opt = 1 / sqrt(1 / ALPHA1 / ALPHA1 + 1 / ALPHA2 / ALPHA2 + 1 / ETA / ETA);

# Print detailed configuration
if (verbose) {
    printf("ILL_D2B: Detailed DIF configuration\n");
    printf("* Incoming beam: lambda=%.4g [Angs] EI=%.4g [meV]  KI=%.4g [Angs-1] Vi=%g [m/s]\n", 
           lambda, EI, KI, Vi);
    printf("* Monochromator:  DM=%.4g [Angs] RV=%.4g [m] %s, take-off 2*THETA_M=%.4g [deg]\n", 
           DM, RV, (!RV ? "flat" : "curved"), THETA_M * 2);
    printf("* Resolution:     Caglioti              U=%g V=%g W=%g [deg^2]\n", U / 60 / 60, V / 60 / 60, W / 60 / 60);
    printf("                  Optimal          ALPHA3=%g [min]\n",  ALPHA3_Opt);
    printf("                  Optimal resolution A1/2=%g [min]\n",  ALPHA3_Opt / sqrt(2));
    printf("                  Normalized Intensity L0=%g [min^3]\n", L0);
}

# Set RV to absolute value
RV = fabs(RV) * SM;

# Define options for wavelength monitor
string lamopts = "lambda limits=[%g, %g]";
lamopts = sprintf(lamopts, lambda * 0.99, lambda * 1.01);

# Define components
component Progress_bar {
    type = Progress_bar
    x = 0
