        transmission = 1.0
    }
    # Only create if ALPHA1 > 0
    if (ALPHA1 > 0) {
        create_component
    }
}

component Slit_Mono {
    type = Slit
    x = 0
    y = 0
    z = L1 - 0.1
    RELATIVE = Origin
    ROTATED = [0, 0, 0]
    parameters = {
        xwidth = 0.05
        yheight = 0.3
    }
}

component D2B_Mono_XY {
    type = Monitor_nD
    x = 0
    y = 0
    z = 0
    RELATIVE = Slit_Mono
    ROTATED = [0, 0, 0]
    parameters = {
        xwidth = 0.1
        yheight = 0.3
        bins = 40
        restore_neutron = 1
        options = "x y"
    }
}

component D2B_ALPHA1_Div {
    type = Monitor_nD
    x = 0
    y = 0
    z = 0
    RELATIVE = D2B_Mono_XY
    ROTATED = [0, 0, 0]
    parameters = {
        xwidth = 0.1
        yheight = 0.3
        bins = 40
