    split = 10
}

component sphere {
    type = PSD_monitor_4PI
    x = 0
    y = 0
    z = 0
    RELATIVE = mono_cradle
    ROTATED = [0, 0, 0]
    parameters = {
        filename = "sphere"
        radius = 0.5
        restore_neutron = 1
    }
}

component mono_out {
    type = Arm
    x = 0
    y = 0
    z = 0
