    type = Monitor_nD
    x = 0
    y = 0
    z = 0
    RELATIVE = D2B_ALPHA2_Div
    ROTATED = [0, 0, 0]
    parameters = {
        xwidth = 0.02
        yheight = 0.05
        bins = 40
        restore_neutron = 1
        options = lamopts
    }
}

component Arm_Sample {
    type = Arm
    x = 0
    y = 0
    z = L2
    RELATIVE = mono_out
    ROTATED = [0, 0, 0]
}

component Container_in {
    type = PowderN
    x = 0
    y = 0
    z = 0
    RELATIVE = Arm_Sample
    ROTATED = [0, 0, 0]
    parameters = {
        reflections = "V.lau"
        radius = 0.0025 + 0.00051
        yheight = 0.04
        thickness = 0.0005
        d_phi = RAD2DEG * atan2(Dheight + 0.05, L3)
        p_interact = 0.1
        concentric = 1
    }
}

component Sample {
    type = PowderN
    x = 0
    y = 0
    z = 0
    RELATIVE = Arm_Sample
    ROTATED = [0, 0, 0]
    parameters = {
        reflections = Powder
        radius = 0.0025
        yheight = 0.04
        d_phi = RAD2DEG * atan2(Dheight + 0.05, L3)
    }
}

component Container_out {
    type = PowderN
    x = 0
    y = 0
    z = 0
    RELATIVE = Arm_Sample
    ROTATED = [0, 0, 0]
    parameters = {
        reflections = "V.lau"
        radius = 0.0025 + 0.00051
        yheight = 0.04
        thickness = 0.0005
        d_phi = RAD2DEG * atan2(Dheight + 0.05, L3)
        p_interact = 0.1
        concentric = 1
    }
}

component collimador_radial {
    type = Collimator_radial
    x = 0
    y = 0
    z = 0
    RELATIVE = Sample
    ROTATED = [0, 0, 0]
    parameters = {
        yheight = Dheight
        length = 0.30
        divergence = ALPHA3
        theta_min = -165
        theta_max = -5
        radius = L3 - 0.3 - 0.01
        verbose = 1
        approx = 1
    }
    # Only create if ALPHA3 > 0
    if (ALPHA3 > 0) {
        create_component
    }
}

component D2B_BananaTheta {
    type = Monitor_nD
    x = 0
    y = 0
    z = 0
    RELATIVE = Sample
    ROTATED = [0, 0, 0]
    parameters = {
        yheight = Dheight
        restore_neutron = 1
        radius = L3
        options = "banana, angle limits=[5 165], bins=3200"
    }
}

component D2B_BananaThetaCenter {
    type = Monitor_nD
    x = 0
    y = 0
    z = 0
    RELATIVE = Sample
    ROTATED = [0, 0, 0]
    parameters = {
        yheight = 0.1
        restore_neutron = 1
        radius = L3
        options = "banana, angle limits=[5 165], bins=3200"
    }
}

component D2B_BananaPSD {
    type = Monitor_nD
    x = 0
    y = 0
    z = 0
    RELATIVE = Sample
    ROTATED = [0, 0, 0]
    parameters = {
        yheight = Dheight
        radius = L3 * 1.005
        options = "banana, theta limits=[-165 -5] bins=320, y bins=25"
    }
}

# Main instrument
instrument ILL_D2B {
    # Define components
    components = {
        Progress_bar
        Source_gen
        Win0
        Oct1
        Oct2
        Win1
        Win2
        Win3
        Win4
        Win5
        Win6
        SMguide
        Alpha_One
        Slit_Mono
        D2B_Mono_XY
        D2B_ALPHA1_Div
        D2B_Mono_Lambda
        mono_cradle
        Monok
        sphere
        mono_out
        Shield_Hole
        Alpha_Two
        Slit_Sample
        D2B_ALPHA2_Div
        D2B_Sample_Lambda
        Arm_Sample
        Container_in
        Sample
        Container_out
        collimador_radial
        D2B_BananaTheta
        D2B_BananaThetaCenter
        D2B_BananaPSD
    }

    # Set parameters
    parameters = {
        lambda = 1
        DM = 0
        Powder = "Na2Ca3Al2F14.laz"
        RV = -1
        L1 = 16.05
        L2 = 2.645
        L3 = 1.3
        verbose = 1
        ALPHA1 = 18
        ALPHA2 = 11
        ALPHA3 = 5
        ETA = 12
        THETA_M = 67.5
        TILT = 0
        SM = 1
        Dheight = 0.3
        coating = 0
    }

    # Set seed and ncount
    seed = 123456789
    ncount = 1e6
}
